def backfill_task_center_fields(apps, schema_editor):
    BusinessTask = apps.get_model("workflow", "BusinessTask")
    source_models = [
        ("customers", "CustomerTaskLink", "CUSTOMER_FOLLOW_UP"),
        ("crm", "CommunicationTaskLink", "COMMUNICATION_FOLLOW_UP"),
        ("inquiries", "InquiryTaskLink", "INQUIRY_RESPONSE"),
        ("quotations", "QuotationVersionTaskLink", "QUOTATION_FOLLOW_UP"),
        ("samples", "SampleTaskLink", "SAMPLE_FEEDBACK"),
    ]
    source_links = [(apps.get_model(app_label, model_name), task_type) for app_label, model_name, task_type in source_models]
    counters = {}
    shanghai = ZoneInfo("Asia/Shanghai")
    for task in BusinessTask.objects.order_by("created_at", "id").iterator():
        created_at = task.created_at.astimezone(shanghai) if task.created_at else None
        year = created_at.year if created_at else 2026
        counters[year] = counters.get(year, 0) + 1
        task.task_number = f"TASK-{year}-{counters[year]:04d}"
        task.origin_type = "AUTOMATION" if task.automation_key else "MANUAL"
        task.origin_code = task.automation_key or ""
        for link_model, task_type in source_links:
            if link_model.objects.filter(business_task_id=task.pk, is_primary_source=True).exists():
                task.task_type = task_type
                break
        task.save(update_fields=["task_number", "origin_type", "origin_code", "task_type"])


def clear_task_center_numbers(apps, schema_editor):
    BusinessTask = apps.get_model("workflow", "BusinessTask")
    BusinessTask.objects.update(task_number=None)


